import Database from "better-sqlite3";
import { existsSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";

export interface ChatMessage {
  room: string;
  seq: number;
  user: string;
  text: string;
  ts: number;
}

const DB_PATH = join(process.cwd(), "data", "chat.db");

function ensureDir(path: string) {
  const dir = dirname(path);
  if (!existsSync(dir)) {
    mkdirSync(dir, { recursive: true });
  }
}

ensureDir(DB_PATH);

const db = new Database(DB_PATH);

db.pragma("journal_mode = WAL");
db.pragma("synchronous = NORMAL");

db.exec(`
  CREATE TABLE IF NOT EXISTS messages (
    room TEXT NOT NULL,
    seq INTEGER NOT NULL,
    user TEXT NOT NULL,
    text TEXT NOT NULL,
    ts INTEGER NOT NULL,
    PRIMARY KEY (room, seq)
  );
`);

const getMaxSeqStmt = db.prepare<[string], { maxSeq: number | null }>(
  "SELECT MAX(seq) AS maxSeq FROM messages WHERE room = ?",
);

const insertStmt = db.prepare<
  { room: string; seq: number; user: string; text: string; ts: number },
  unknown
>(
  "INSERT INTO messages (room, seq, user, text, ts) VALUES (@room, @seq, @user, @text, @ts)",
);

/**
 * Atomically assigns the next sequence number for a room, and persists the
 * message. Because better-sqlite3 executes synchronously and this whole
 * function runs inside a single DB transaction, no interleaving with other
 * concurrent requests can occur, guaranteeing gapless, unique, monotonically
 * increasing sequence numbers per room even under heavy concurrency.
 */
const insertMessageTx = db.transaction(
  (room: string, user: string, text: string, ts: number): ChatMessage => {
    const row = getMaxSeqStmt.get(room);
    const nextSeq = row && typeof row.maxSeq === "number" ? row.maxSeq + 1 : 1;
    insertStmt.run({ room, seq: nextSeq, user, text, ts });
    return { room, seq: nextSeq, user, text, ts };
  },
);

export function insertMessage(
  room: string,
  user: string,
  text: string,
  ts: number,
): ChatMessage {
  return insertMessageTx(room, user, text, ts);
}

const getRecentStmt = db.prepare<[string, number], ChatMessage>(
  "SELECT room, seq, user, text, ts FROM messages WHERE room = ? ORDER BY seq DESC LIMIT ?",
);

/** Returns the most recent `limit` messages for a room, in ascending seq order. */
export function getRecentMessages(room: string, limit: number): ChatMessage[] {
  const rows = getRecentStmt.all(room, limit);
  return rows.reverse();
}

const getAfterStmt = db.prepare<[string, number], ChatMessage>(
  "SELECT room, seq, user, text, ts FROM messages WHERE room = ? AND seq > ? ORDER BY seq ASC",
);

/** Returns all messages for a room with seq strictly greater than `afterSeq`, in ascending order. */
export function getMessagesAfter(room: string, afterSeq: number): ChatMessage[] {
  return getAfterStmt.all(room, afterSeq);
}

export default db;

import type { ChatMessage } from "./db";

type Listener = (message: ChatMessage) => void;

/**
 * A simple in-memory pub/sub broker, scoped per room. This is the only
 * fan-out mechanism used to deliver newly published messages to live SSE
 * subscribers; it never touches the network or any external service.
 */
class RoomBroker {
  private rooms = new Map<string, Set<Listener>>();

  subscribe(room: string, listener: Listener): () => void {
    let set = this.rooms.get(room);
    if (!set) {
      set = new Set();
      this.rooms.set(room, set);
    }
    set.add(listener);

    let unsubscribed = false;
    return () => {
      if (unsubscribed) return;
      unsubscribed = true;
      const current = this.rooms.get(room);
      if (current) {
        current.delete(listener);
        if (current.size === 0) {
          this.rooms.delete(room);
        }
      }
    };
  }

  publish(room: string, message: ChatMessage): void {
    const set = this.rooms.get(room);
    if (!set || set.size === 0) return;
    // Snapshot the listeners so that a listener unsubscribing mid-publish
    // (e.g. due to a write error) can't corrupt iteration.
    for (const listener of Array.from(set)) {
      try {
        listener(message);
      } catch {
        // Listeners must handle their own errors; ignore here to keep
        // delivery to other subscribers unaffected.
      }
    }
  }

  subscriberCount(room: string): number {
    return this.rooms.get(room)?.size ?? 0;
  }
}

export const broker = new RoomBroker();

import type { RequestHandler } from "@builder.io/qwik-city";
import { insertMessage } from "~/lib/db";
import { broker } from "~/lib/broker";

const MIN_USER_LEN = 1;
const MAX_USER_LEN = 64;
const MIN_TEXT_LEN = 1;
const MAX_TEXT_LEN = 2000;

export const onPost: RequestHandler = async (ev) => {
  const room = ev.params.room;

  let body: unknown;
  try {
    body = await ev.request.json();
  } catch {
    ev.json(400, { error: "Request body must be valid JSON" });
    return;
  }

  if (typeof body !== "object" || body === null || Array.isArray(body)) {
    ev.json(400, { error: "Request body must be a JSON object" });
    return;
  }

  const rawUser = (body as Record<string, unknown>).user;
  const rawText = (body as Record<string, unknown>).text;

  if (typeof rawUser !== "string") {
    ev.json(400, { error: "'user' is required and must be a string" });
    return;
  }
  if (typeof rawText !== "string") {
    ev.json(400, { error: "'text' is required and must be a string" });
    return;
  }

  const user = rawUser.trim();
  const text = rawText.trim();

  if (user.length < MIN_USER_LEN || user.length > MAX_USER_LEN) {
    ev.json(400, {
      error: `'user' must be between ${MIN_USER_LEN} and ${MAX_USER_LEN} characters after trimming`,
    });
    return;
  }

  if (text.length < MIN_TEXT_LEN || text.length > MAX_TEXT_LEN) {
    ev.json(400, {
      error: `'text' must be between ${MIN_TEXT_LEN} and ${MAX_TEXT_LEN} characters after trimming`,
    });
    return;
  }

  const ts = Date.now();
  const message = insertMessage(room, user, text, ts);

  broker.publish(room, message);

  ev.json(201, message);
};

import type { RequestHandler } from "@builder.io/qwik-city";
import { broker } from "~/lib/broker";

export const onGet: RequestHandler = async (ev) => {
  const room = ev.params.room;
  ev.json(200, {
    room,
    subscribers: broker.subscriberCount(room),
  });
};

import type { RequestHandler } from "@builder.io/qwik-city";
import { getMessagesAfter, getRecentMessages, type ChatMessage } from "~/lib/db";
import { broker } from "~/lib/broker";

const DEFAULT_REPLAY_LIMIT = 50;

export const onGet: RequestHandler = async (ev) => {
  const room = ev.params.room;

  ev.headers.set("Content-Type", "text/event-stream; charset=utf-8");
  ev.headers.set("Cache-Control", "no-cache, no-transform");
  ev.headers.set("Connection", "keep-alive");
  // Prevent reverse proxies (e.g. nginx) from buffering the stream.
  ev.headers.set("X-Accel-Buffering", "no");

  const writer = ev.getWritableStream().getWriter();
  const encoder = new TextEncoder();

  let closed = false;
  let writeChain: Promise<void> = Promise.resolve();

  const frameOf = (msg: ChatMessage) =>
    `id: ${msg.seq}\nevent: message\ndata: ${JSON.stringify(msg)}\n\n`;

  const rawWrite = async (msg: ChatMessage) => {
    if (closed) return;
    try {
      await writer.write(encoder.encode(frameOf(msg)));
    } catch {
      teardown();
    }
  };

  // Chaining each write onto a single promise chain guarantees strict
  // in-order delivery on the wire: a write is only started once the
  // previous one has settled. Combined with the fact that `enqueue` is
  // always invoked synchronously (either from the backlog loop below, or
  // synchronously from the broker's `publish`), the order in which
  // `enqueue` is called is exactly the order messages are written.
  const enqueue = (msg: ChatMessage) => {
    writeChain = writeChain.then(() => rawWrite(msg));
  };

  function teardown() {
    if (closed) return;
    closed = true;
    unsubscribe();
    writer.close().catch(() => {});
  }

  // Subscribe FIRST, synchronously. From this instant on, any message
  // published to this room is delivered to `enqueue`. The backlog query
  // immediately below is also fully synchronous (better-sqlite3 is a
  // blocking API) with no `await` in between, so there is no window in
  // which the JS event loop could run other code (e.g. a concurrent POST
  // publishing a message). This makes it impossible to miss a message
  // published concurrently with connecting, and impossible to duplicate a
  // message that is already included in the backlog snapshot.
  const unsubscribe = broker.subscribe(room, enqueue);

  const lastEventIdHeader = ev.request.headers.get("Last-Event-ID");
  let backlog: ChatMessage[];
  if (lastEventIdHeader !== null && /^-?\d+$/.test(lastEventIdHeader.trim())) {
    const lastSeq = parseInt(lastEventIdHeader.trim(), 10);
    backlog = getMessagesAfter(room, lastSeq);
  } else {
    backlog = getRecentMessages(room, DEFAULT_REPLAY_LIMIT);
  }

  for (const msg of backlog) {
    enqueue(msg);
  }

  if (ev.signal.aborted) {
    teardown();
    return;
  }

  await new Promise<void>((resolve) => {
    ev.signal.addEventListener("abort", () => resolve(), { once: true });
  });

  teardown();
};

